from pathlib import Path
def put(p,s):Path(p).write_bytes(s.encode('utf-8'))
p=Path('apps/web/src/views/Models.vue');s=p.read_text();s=s.replace('每一次训练，都有迹可循。','训练实验').replace('运行表现，逐项对照。','性能对照')
s=s.replace('    ><span class="right inline-count">{{ list.total.value }} 条记录</span>','''    ><template v-if="['training','deployments'].includes(tab)"><select v-model="list.sort.value" aria-label="排序字段" @change="list.filter"><option value="createdAt">创建时间</option><option value="name">名称</option></select><select v-model="list.order.value" aria-label="排序方向" @change="list.filter"><option value="desc">降序</option><option value="asc">升序</option></select></template><span class="right inline-count">{{ list.total.value }} 条记录</span>''',1)
s=s.replace('    ><div class="panel table-wrap">','''    ><section v-if="tab === 'training'" class="experiment-log" aria-label="训练实验记录"><article v-for="(r, index) in list.items.value" :key="r.id" class="experiment-entry"><div class="experiment-time"><span class="mono">{{ String((list.page.value - 1) * list.pageSize.value + index + 1).padStart(3,'0') }}</span><time>{{ new Date(r.createdAt).toLocaleDateString() }}</time><small class="mono">{{ new Date(r.createdAt).toLocaleTimeString() }}</small></div><div class="experiment-body"><div class="experiment-entry-head"><h3>{{ displayName(r.name) }}</h3><Status :value="r.status" /></div><div class="experiment-source"><span class="tag" :class="{ simulated: r.source === 'SIMULATION' }">{{ chinese(r.source) }}</span><span class="mono">{{ r.id.slice(-10) }}</span><span>{{ chinese(text(r,'stage')) }}</span></div><div class="experiment-progress"><div class="bar"><span :style="{ width: `${r.progress ?? 0}%` }" /></div><span class="mono">{{ r.progress === undefined ? '—' : `${r.progress}%` }}</span></div><p v-if="r.error" class="tone-crit">{{ r.error }}</p></div><div class="experiment-actions"><button @click="open(r)">实验详情</button><button v-if="['QUEUED','RUNNING'].includes(r.status ?? '')" @click="action(r.id,'cancel')" :disabled="busy" class="danger">取消任务</button></div></article></section>
    <section v-else-if="tab === 'deployments'" class="deployment-console" aria-label="部署执行记录"><article v-for="r in list.items.value" :key="r.id" class="deployment-entry"><header><div><span class="mono">{{ r.id.slice(-10) }}</span><h3>{{ displayName(r.name) }}</h3></div><Status chip :value="r.status" /></header><div class="deployment-route"><div><small>当前目标</small><b>{{ displayName((r.model as Model | undefined)?.name ?? text(r,'modelId')) }}</b><span class="mono">{{ (r.model as Model | undefined)?.version ?? '—' }}</span></div><span class="deployment-arrow">→</span><div><small>接收设备</small><b>{{ devices.devices.find(d => d.id === r.deviceId)?.name ?? text(r,'deviceId') }}</b><span class="mono">{{ r.previousVersion ? `前序版本 ${r.previousVersion}` : '无前序版本' }}</span></div></div><div class="deployment-progress"><Status :value="r.status" /><span>{{ chinese(text(r,'stage')) }}</span><div class="bar"><span :style="{ width: `${r.progress ?? 0}%` }" /></div><b class="mono">{{ r.progress === undefined ? '—' : `${r.progress}%` }}</b></div><p v-if="r.error" class="error-box">{{ r.error }}</p><footer><span class="tag" :class="{ simulated: r.source === 'SIMULATION' }">{{ chinese(r.source) }}</span><time class="mono">{{ new Date(r.createdAt).toLocaleString() }}</time><button @click="open(r)">执行证据</button><button v-if="r.previousVersion && ['ACTIVE','FAILED'].includes(r.status ?? '')" :disabled="busy" @click="action(r.id,'rollback')" class="danger">回滚版本</button></footer></article></section>
    <div v-else class="panel table-wrap">''',1);put(p,s)
p=Path('apps/web/src/views/Data.vue');s=p.read_text().replace('整理、冻结、复现。','数据集版本');put(p,s)
p=Path('apps/web/src/views/Overview.vue');s=p.read_text().replace('v-for="s in data.loop"','v-for="(s, stepIndex) in data.loop"').replace('<span class="label">{{ s.label }}</span>','<small class="stage-index mono">{{ String(stepIndex + 1).padStart(2, "0") }}</small><span class="label">{{ s.label }}</span>');put(p,s)
p=Path('apps/mobile/src/pages/capture/index.vue');s=p.read_text().replace('<text class="record-symbol">▤</text>','<text class="record-symbol">记录</text>');put(p,s)
